from typing import Iterator, Callable, Any

class DataPipeline:
    def __init__(self, validators: list[Callable[[dict], bool]] = None):
        self.validators = list(validators) if validators is not None else []

    def process_stream(self, records: list[dict[str, Any]]) -> Iterator[dict[str, Any]]:
        for rec in records:
            valid = True
            for v in self.validators:
                try:
                    if not v(rec):
                        valid = False
                        break
                except Exception:
                    valid = False
                    break
            if valid:
                yield rec
